1	package darksafe
2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// publishReviewPair publishes version 1 in both organizations with the same
9	// subject, action, scope and policy id, but opposite effects: acme allows,
10	// globex denies. Every identifier coincides so only the selected decision
11	// organization can explain a differing review outcome.
12	func publishReviewPair(t *testing.T, s *Store) {
13		t.Helper()
14		shared := Policy{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow}
15		if v, err := s.Publish("acme", 0, []Policy{shared}); err != nil || v != 1 {
16			t.Fatalf("acme publish = %d, %v; want 1, nil", v, err)
17		}
18		shared.Effect = EffectDeny
19		if v, err := s.Publish("globex", 0, []Policy{shared}); err != nil || v != 1 {
20			t.Fatalf("globex publish = %d, %v; want 1, nil", v, err)
21		}
22	}
23	
24	func TestReviewOrgIsolationOppositeOutcomes(t *testing.T) {
25		s := NewStore()
26		publishReviewPair(t, s)
27	
28		// Same subject, resource, action, scope and policy id in both
29		// organizations; only the decision organization differs.
30		allow := s.Review("acme", 1, request("acme", "u1", "r1", "org/a", "read"))
31		if !allow.Allowed || allow.Reason != "matched allow policy" {
32			t.Fatalf("acme review = %+v, want allowed with matched allow policy", allow)
33		}
34		if !reflect.DeepEqual(allow.Matched, []string{"p1"}) {
35			t.Fatalf("acme matched = %v, want [p1] only", allow.Matched)
36		}
37		if allow.Version != 1 {
38			t.Fatalf("acme version = %d, want 1", allow.Version)
39		}
40	
41		deny := s.Review("globex", 1, request("globex", "u1", "r1", "org/a", "read"))
42		if deny.Allowed || deny.Reason != "matched deny policy" {
43			t.Fatalf("globex review = %+v, want denied with matched deny policy", deny)
44		}
45		if !reflect.DeepEqual(deny.Matched, []string{"p1"}) {
46			t.Fatalf("globex matched = %v, want [p1] only", deny.Matched)
47		}
48		if deny.Version != 1 {
49			t.Fatalf("globex version = %d, want 1", deny.Version)
50		}
51	}
52	
53	func TestReviewOrgIsolationVersionExistence(t *testing.T) {
54		s := NewStore()
55		publishReviewPair(t, s)
56		before := s.Review("acme", 1, request("acme", "u1", "r1", "org/a", "read"))
57		if !before.Allowed {
58			t.Fatalf("acme v1 review before v2 publish = %+v, want allowed", before)
59		}
60	
61		// Only acme publishes a version 2, flipping its current decision to deny.
62		// globex never has a version 2.
63		denyV2 := Policy{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectDeny}
64		if v, err := s.Publish("acme", 1, []Policy{denyV2}); err != nil || v != 2 {
65			t.Fatalf("acme second publish = %d, %v; want 2, nil", v, err)
66		}
67		if got := s.CurrentVersion("globex"); got != 1 {
68			t.Fatalf("globex current = %d, want 1", got)
69		}
70	
71		// Reviewing acme's version 1 still replays the historical allow, not the
72		// current deny.
73		after := s.Review("acme", 1, request("acme", "u1", "r1", "org/a", "read"))
74		if !reflect.DeepEqual(before, after) {
75			t.Fatalf("acme v1 review changed after v2 publish: before=%+v after=%+v", before, after)
76		}
77	
78		// globex has no version 2 even though acme does and every identifier
79		// coincides: no fallback to globex's current set or acme's version 2.
80		d := s.Review("globex", 2, request("globex", "u1", "r1", "org/a", "read"))
81		if d.Allowed || d.Reason != "version 2 not found" {
82			t.Fatalf("globex v2 review = %+v, want denied with version 2 not found", d)
83		}
84		if d.Version != 0 {
85			t.Fatalf("globex v2 review version = %d, want 0", d.Version)
86		}
87		if len(d.Matched) != 0 {
88			t.Fatalf("globex v2 review matched = %v, want empty", d.Matched)
89		}
90	}
91	
92	func TestReviewOrgIsolationOrgMismatch(t *testing.T) {
93		s := NewStore()
